package com.example.erp.controller.mvc;
import java.util.LinkedHashMap; import java.util.Locale; import java.util.Map; import java.util.UUID; import org.springframework.context.MessageSource; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import com.example.erp.service.PaymentService;
@Controller public class PaymentsPageController { private static final String[] KEYS={"payments.title","payments.eyebrow","payments.heading","payments.description","payments.nav.dashboard","payments.nav.logout","payments.action.add","payments.action.search","payments.action.void","payments.action.post","payments.action.detail","payments.filter.keyword","payments.filter.status","payments.filter.all","payments.table.receipt","payments.table.payer","payments.table.amount","payments.table.date","payments.table.status","payments.table.actions","payments.status.pending_deposit","payments.status.posted","payments.status.voided","payments.loading","payments.empty","payments.form.title","payments.form.category","payments.form.payer","payments.form.reason","payments.form.note","payments.form.amount","payments.form.currency","payments.form.method","payments.form.date","payments.form.bank_account","payments.form.save","payments.form.cancel","payments.error.load","payments.error.save","payments.success.created","payments.success.voided","payments.confirm.void_title","payments.confirm.text","payments.confirm.confirm","payments.confirm.cancel","payments.pagination.previous","payments.pagination.next","payments.pagination.of","common.error.network","common.error.timeout","common.error.request_failed"}; private final MessageSource messages; private final PaymentService service; public PaymentsPageController(MessageSource messages,PaymentService service){this.messages=messages;this.service=service;}
 @GetMapping("/payments") public String payments(Model model,Locale locale){Map<String,String> values=new LinkedHashMap<>();for(String key:KEYS)values.put(key,messages.getMessage(key,null,locale));model.addAttribute("messages",values);return "payments/list";}
 @GetMapping("/payments/receipt/{id}") public String receipt(@PathVariable UUID id,Model model){model.addAttribute("payment",service.detail(id));return "payments/receipt";}
}
